from __future__ import annotations

import functools
import threading
import time
from collections import OrderedDict
from typing import Any, Callable, Generic, Optional, TypeVar, overload

K = TypeVar("K")
V = TypeVar("V")
F = TypeVar("F", bound=Callable[..., Any])

_MISSING = object()


class LRUCache(Generic[K, V]):
    """Thread-safe least-recently-used cache with optional TTL expiry.

    Args:
        maxsize: Maximum number of entries retained. Must be >= 1.
        ttl: Optional time-to-live in seconds. Entries expire after this
            many seconds. Must be > 0 when provided.

    Entries are evicted in least-recently-used order when the cache exceeds
    ``maxsize``. Accessing an entry marks it as most recently used.
    """

    def __init__(self, maxsize: int = 128, ttl: Optional[float] = None) -> None:
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be > 0")
        self.maxsize = maxsize
        self.ttl = ttl
        self._data: OrderedDict[K, tuple[V, Optional[float]]] = OrderedDict()
        self._lock = threading.RLock()

    def _now(self) -> float:
        return time.monotonic()

    def _is_expired(self, expires_at: Optional[float]) -> bool:
        return expires_at is not None and expires_at <= self._now()

    def get(self, key: K, default: Optional[V] = None) -> Optional[V]:
        """Return the cached value for ``key``, or ``default`` if missing/expired."""
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return default
            value, expires_at = item
            if self._is_expired(expires_at):
                del self._data[key]
                return default
            self._data.move_to_end(key)
            return value

    def set(self, key: K, value: V) -> V:
        """Store ``value`` under ``key``, evicting the least-recently-used entry if needed."""
        with self._lock:
            expires_at = None if self.ttl is None else self._now() + self.ttl
            if key in self._data:
                self._data.pop(key)
            self._data[key] = (value, expires_at)
            self._data.move_to_end(key)
            while len(self._data) > self.maxsize:
                self._data.popitem(last=False)
            return value

    def delete(self, key: K) -> bool:
        """Delete ``key`` if present. Returns True if an entry was removed."""
        with self._lock:
            if key in self._data:
                del self._data[key]
                return True
            return False

    def clear(self) -> None:
        """Remove all entries."""
        with self._lock:
            self._data.clear()

    def __getitem__(self, key: K) -> V:
        value = self.get(key)
        if value is None:
            raise KeyError(key)
        return value

    def __setitem__(self, key: K, value: V) -> None:
        self.set(key, value)

    def __contains__(self, key: K) -> bool:
        return self.get(key, _MISSING) is not _MISSING  # type: ignore[return-value]

    def __len__(self) -> int:
        with self._lock:
            expired = [k for k, (_, exp) in self._data.items() if self._is_expired(exp)]
            for k in expired:
                del self._data[k]
            return len(self._data)


@overload
def lru_cache(func: F) -> F: ...


@overload
def lru_cache(
    maxsize: int = 128,
    ttl: Optional[float] = None,
) -> Callable[[F], F]: ...


def lru_cache(
    func: Optional[F] = None,
    *,
    maxsize: int = 128,
    ttl: Optional[float] = None,
) -> Any:
    """Decorator that caches a function's return value using an LRU cache.

    Can be used as ``@lru_cache`` or ``@lru_cache(maxsize=..., ttl=...)``.
    Arguments must be hashable; keyword arguments are included in the cache key.

    Args:
        func: The function to decorate when used without arguments.
        maxsize: Maximum number of cached results.
        ttl: Optional TTL in seconds for cached results.

    Returns:
        A decorator or decorated function. The decorated function exposes a
        ``cache`` attribute holding its underlying ``LRUCache``.
    """

    def decorator(f: F) -> F:
        cache: LRUCache[tuple[Any, ...], Any] = LRUCache(maxsize=maxsize, ttl=ttl)

        @functools.wraps(f)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            key = (args, tuple(sorted(kwargs.items())))
            cached = cache.get(key, _MISSING)  # type: ignore[arg-type]
            if cached is not _MISSING:
                return cached
            result = f(*args, **kwargs)
            cache.set(key, result)
            return result

        wrapper.cache = cache  # type: ignore[attr-defined]
        return wrapper  # type: ignore[return-value]

    if func is not None:
        return decorator(func)
    return decorator


__all__ = ["LRUCache", "lru_cache"]
